const $=s=>document.querySelector(s),key='careerflow-v1';
const defaults={jobs:[],profile:{name:'Mariana Viana Ferreira',email:'marianaviana121@gmail.com',summary:'',cv:''},rules:{keywords:'DevOps, Cloud, SRE, Azure, Kubernetes',remote:true,auto:true,template:'Olá, equipe de recrutamento da {empresa}!\n\nTenho interesse na oportunidade de {cargo}.\n{resumo}\n\nFico à disposição para conversar.\n{nome}\n{email}'}};
let state=structuredClone(defaults),current=null,loadFailure=false,rawSaved=null;try{rawSaved=localStorage.getItem(key);if(rawSaved)state=CareerData.restore(JSON.parse(rawSaved),defaults);}catch{loadFailure=true;}let persistedState=structuredClone(state);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){(document.querySelector('dialog[open]')||document.body).append($('#toast'));$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){try{if(loadFailure)throw Error('Recupere o backup antes de salvar');localStorage.setItem(key,JSON.stringify(state));persistedState=structuredClone(state);window.dispatchEvent(new Event('careerflow:change'));return true}catch{state=structuredClone(persistedState);document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();window.dispatchEvent(new Event('careerflow:change'));toast(loadFailure?'Dados antigos inválidos. Restaure um backup válido antes de salvar.':'Não foi possível salvar. A alteração foi desfeita; libere espaço e tente novamente.');return false}}
function safeUrl(v){return CareerData.url(v)}
function canonical(v){return CareerData.canonical(v)}
function score(j){let words=state.rules.keywords.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean),text=(j.role+' '+j.description).toLowerCase();return words.filter(w=>text.includes(w)).length+(state.rules.remote&&j.mode==='Remoto'?1:0)}
function message(j){let p=state.profile,dict={nome:p.name,email:p.email,resumo:p.summary,cargo:j.role,empresa:j.company};return state.rules.template.replace(/\{(nome|email|resumo|cargo|empresa)\}/g,(_,k)=>dict[k])+(p.cv?'\n\nCurrículo: '+p.cv:'')}
const labels={dashboard:['Visão geral','Sua carreira, em movimento.','Organize suas oportunidades. Foque no que vem depois.'],jobs:['Minhas candidaturas','Cada oportunidade, um novo caminho.','Todas as suas candidaturas em um só lugar.'],rules:['Automações','Sua rotina, com menos repetição.','Configure a preparação das suas candidaturas.'],profile:['Perfil e currículo','Sua história abre portas.','Mantenha seus dados prontos para o próximo contato.']};
function view(v){for(const id of ['dashboard','jobs','bottom','rules','profile'])$('#'+id).hidden=!(v==='dashboard'?['dashboard','jobs','bottom'].includes(id):id===v);$('h1').textContent=labels[v][1];$('#subtitle').textContent=labels[v][2];$('#pageLabel').textContent=labels[v][0];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#addTop').hidden=!['dashboard','jobs'].includes(v);if(v==='rules'||v==='profile'){let f=$('#'+v+'Form');for(let [k,val] of Object.entries(state[v]))if(f.elements[k])f.elements[k].type==='checkbox'?f.elements[k].checked=val:f.elements[k].value=val}window.scrollTo(0,0)}
function render(){let jobs=state.jobs;$('#sTotal').textContent=jobs.length;$('#sPrep').textContent=jobs.filter(j=>j.status==='Salva').length;$('#sSent').textContent=jobs.filter(j=>['Enviada','Entrevista'].includes(j.status)).length;$('#sInterview').textContent=jobs.filter(j=>j.status==='Entrevista').length;$('#count').textContent=jobs.length;$('#navCount').textContent=jobs.length;let q=$('#search').value.toLowerCase(),list=jobs.filter(j=>(j.role+' '+j.company).toLowerCase().includes(q)&&(!$('#statusFilter').value||j.status===$('#statusFilter').value)&&(!$('#modeFilter').value||j.mode===$('#modeFilter').value)).sort((a,b)=>score(b)-score(a));$('#jobList').innerHTML=list.length?list.map(j=>`<div class="job-row"><div class="company-icon">${esc(j.company.charAt(0).toUpperCase())}</div><div class="job-info"><strong>${esc(j.role)}</strong><small>${esc(j.company)} · ${esc(j.mode)}</small></div><span class="badge" title="Pontos por palavra-chave e modalidade; não é avaliação de qualificação">${score(j)} pontos de prioridade</span><span class="badge">${esc(j.status)}</span><button class="text-btn" data-detail="${esc(j.id)}">Ver detalhes ↗</button></div>`).join(''):`<div class="empty"><div class="empty-icon">▤</div><h3>${jobs.length?'Nenhuma vaga com esses filtros':'Seu próximo passo começa com uma vaga'}</h3><p>${jobs.length?'Tente outro cargo, empresa ou status.':'Adicione uma oportunidade para organizar sua candidatura.<br>As vagas reais que você salvar aparecerão aqui.'}</p>${jobs.length?'':'<button class="secondary" id="emptyAdd">＋ Adicionar primeira vaga</button>'}</div>`;$('#emptyAdd')?.addEventListener('click',openAdd);document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))}
function openAdd(){$('#jobForm').reset();$('#jobDialog').showModal()}
function detail(id){current=id;let j=state.jobs.find(j=>j.id===id);if(!j)return toast('Esta vaga não está mais no radar');$('#detailTitle').textContent=j.role;$('#detailBody').innerHTML=`<div class="details-meta">${esc(j.company)} · ${esc(j.mode)} · Salva em ${new Date(j.created).toLocaleDateString('pt-BR')}<br>${score(j)} pontos de prioridade pelas suas regras</div><p class="detail-text">${esc(j.description||'Nenhuma descrição adicionada.')}</p><p class="detail-text">${esc(j.notes)}</p><div class="details-actions"><a class="primary" href="${esc(safeUrl(j.url))}" target="_blank" rel="noopener">Abrir vaga ↗</a><button class="secondary" id="prepare">Gerar mensagem</button></div><label>Status<select id="jobStatus">${['Salva','Preparada','Enviada','Entrevista','Encerrada'].map(s=>`<option ${s===j.status?'selected':''}>${s}</option>`).join('')}</select><small>Marque “Enviada” apenas após concluir o envio na plataforma.</small></label><label>Mensagem de apresentação<textarea id="draft" rows="8" placeholder="Clique em gerar mensagem">${esc(j.draft||'')}</textarea></label><div class="details-actions"><button class="secondary" id="copy">Copiar mensagem</button><button class="primary" id="saveDetail">Salvar alterações</button><button class="text-btn danger" id="delete">Excluir vaga</button></div><small>Revise a mensagem antes de usar. Nenhuma candidatura será enviada por este site.</small>`;$('#prepare').onclick=()=>{$('#draft').value=message(j);if($('#jobStatus').value==='Salva')$('#jobStatus').value='Preparada'};$('#saveDetail').onclick=()=>{j.draft=$('#draft').value;j.status=$('#jobStatus').value;if(!save())return;render();toast('Alterações salvas');$('#detailDialog').close()};$('#copy').onclick=async()=>{if(!$('#draft').value)return toast('Gere uma mensagem primeiro');try{await navigator.clipboard.writeText($('#draft').value);toast('Mensagem copiada')}catch{$('#draft').select();toast('Selecione e copie a mensagem com Ctrl+C')}};$('#delete').onclick=()=>{if(confirm('Excluir esta vaga do seu radar?')){state.jobs=state.jobs.filter(x=>x.id!==id);if(state.applications)delete state.applications[id];if(!save())return;render();$('#detailDialog').close();toast('Vaga excluída')}};if(!$('#detailDialog').open)$('#detailDialog').showModal()}
$('#jobForm').onsubmit=e=>{e.preventDefault();let j=Object.fromEntries(new FormData(e.target));j.role=j.role.trim();j.company=j.company.trim();if(!j.role||!j.company)return toast('Preencha o cargo e a empresa');if(!safeUrl(j.url))return toast('Informe um link HTTP ou HTTPS válido');if(state.jobs.some(x=>canonical(x.url)===canonical(j.url)))return toast('Essa vaga já está no seu radar');Object.assign(j,{id:crypto.randomUUID(),created:new Date().toISOString(),status:'Salva',draft:''});if(state.rules.auto){j.draft=message(j);j.status='Preparada'}state.jobs.push(j);if(!save())return;render();$('#jobDialog').close();toast('Vaga adicionada ao radar')};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#addTop').onclick=openAdd;$('#setup').onclick=$('#rulesLink').onclick=()=>view('rules');['search','statusFilter','modeFilter'].forEach(id=>$('#'+id).addEventListener('input',render));
$('#rulesForm').onsubmit=e=>{e.preventDefault();let f=e.target;state.rules={keywords:f.elements.keywords.value,remote:f.elements.remote.checked,auto:f.elements.auto.checked,template:f.elements.template.value};if(!save())return;render();toast('Regras salvas. Aplicadas às próximas preparações.')};
$('#profileForm').onsubmit=e=>{e.preventDefault();let p=Object.fromEntries(new FormData(e.target));if(p.cv&&!safeUrl(p.cv))return toast('Informe um link de currículo HTTP ou HTTPS válido');state.profile=p;if(!save())return false;toast('Perfil salvo');return true};
function download(content,type,name){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#export').onclick=()=>{if(!state.jobs.length)return toast('Adicione uma vaga antes de exportar');let rows=[['Cargo','Empresa','Modalidade','Status','Link','Prioridade','Data','Observações'],...state.jobs.map(j=>[j.role,j.company,j.mode,j.status,j.url,score(j),j.created,j.notes])];download('\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8','candidaturas.csv');toast('CSV exportado')};
$('#backup').onclick=()=>download(loadFailure&&rawSaved?rawSaved:JSON.stringify(state,null,2),'application/json',loadFailure?'careerflow-recuperacao.json':'careerflow-backup.json');
$('#restore').onchange=async e=>{
 try{
  const file=e.target.files[0];if(!file)return;if(file.size>25000000)throw Error('Arquivo acima de 25 MB');
  const data=CareerData.restore(JSON.parse(await file.text()),defaults);
  if(!confirm('Restaurar este backup e substituir os dados atuais?'))return;
  const failed=loadFailure;loadFailure=false;state=data;
  if(!save()){loadFailure=failed;return;}
  render();view('profile');$('#loadWarning')?.remove();window.dispatchEvent(new Event('careerflow:restore'));toast('Backup restaurado');
 }catch{toast('Backup inválido. Nenhum dado foi substituído. Use um arquivo exportado pelo CareerFlow.');}
 finally{e.target.value='';}
};
render();
if(loadFailure){const warning=document.createElement('div');warning.id='loadWarning';warning.className='notice';warning.setAttribute('role','alert');warning.textContent='Não foi possível ler seus dados anteriores. Eles não serão sobrescritos. Em Perfil e currículo, baixe uma cópia para recuperação ou restaure um backup válido.';$('.content').prepend(warning);}
